<?php declare(strict_types=1); ?><!doctype html><html lang="<?= e(\App\Core\Translator::locale()) ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e(villa_ui('Yeni şifre belirle')) ?></title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:#f7f7f7;font-family:system-ui;color:#222}.card{width:min(430px,calc(100% - 32px));padding:30px;background:#fff;border:1px solid #eee;border-radius:18px}label{display:block;font-size:13px;font-weight:650;margin:18px 0 6px}input{width:100%;padding:13px;border:1px solid #ccc;border-radius:9px;font:inherit}button{width:100%;border:0;border-radius:9px;padding:14px;background:#e65362;color:white;font-weight:700;margin-top:20px}.error{color:#a22;background:#fff0f0;padding:10px;border-radius:8px}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="card"><h1><?= e(villa_ui('Yeni şifre belirle')) ?></h1><?php if(!empty($error)): ?><p class="error"><?= e($error) ?></p><?php endif; ?><form method="post" action="<?= e(app_url('/reset-password')) ?>"><?= csrf_field() ?><input type="hidden" name="token" value="<?= e((string)$token) ?>"><label for="password"><?= e(villa_ui('Yeni şifre')) ?></label><input id="password" name="password" type="password" minlength="12" autocomplete="new-password" required><label for="confirm"><?= e(villa_ui('Yeni şifre (tekrar)')) ?></label><input id="confirm" name="password_confirm" type="password" minlength="12" autocomplete="new-password" required><button type="submit"><?= e(villa_ui('Şifreyi kaydet')) ?></button></form></main></body></html>
